[{"order":1,"type":"heading","text":"Unit and Widget Testing Best Practices in Flutter"},{"order":2,"type":"paragraph","text":"Writing robust tests is essential for maintaining a healthy and scalable Flutter application. This guide covers industry standards for structuring, writing, and executing unit and widget tests efficiently."},{"order":3,"type":"subheading","text":"1. Structuring Your Test Directory"},{"order":4,"type":"paragraph","text":"Mirror your lib directory structure inside the test directory. This makes locating corresponding test files intuitive for all developers on the team."},{"order":5,"type":"bullet_point","text":"lib/features/auth/services/auth_service.dart maps to test/features/auth/services/auth_service_test.dart"},{"order":6,"type":"bullet_point","text":"lib/features/auth/widgets/login_form.dart maps to test/features/auth/widgets/login_form_test.dart"},{"order":7,"type":"subheading","text":"2. Writing Effective Unit Tests"},{"order":8,"type":"paragraph","text":"Unit tests should focus on testing a single unit of logic, such as a BLoC, ViewModel, or utility function. Always isolate dependencies using mocking libraries like mocktail."},{"order":9,"type":"code","text":"import 'package:flutter_test/flutter_test.dart';
import 'package:mocktail/mocktail.dart';

class MockApiClient extends Mock implements ApiClient {}

void main() {
  group('AuthRepository', () {
    late AuthRepository authRepository;
    late MockApiClient mockApiClient;

    setUp(() {
      mockApiClient = MockApiClient();
      authRepository = AuthRepository(apiClient: mockApiClient);
    });

    test('returns true when login is successful', () async {
      when(() => mockApiClient.post(any(), any())).thenAnswer((_) async => {'token': '123'});

      final result = await authRepository.login('test@email.com', 'password');

      expect(result, isTrue);
    });
  });
}"},{"order":10,"type":"subheading","text":"3. Writing Resilient Widget Tests"},{"order":11,"type":"paragraph","text":"Widget tests verify that your UI components render correctly and respond to user interactions. UsepumpWidget to wrap your widget in a MaterialApp and pumpAndSettle to wait for animations to complete."},{"order":12,"type":"code","text":"import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  testWidgets('LoginForm displays validation error on empty submit', (WidgetTester tester) async {
    await tester.pumpWidget(
      const MaterialApp(
        home: Scaffold(
          body: LoginForm(),
        ),
      ),
    );

    final loginButton = find.byType(ElevatedButton);
    expect(loginButton, findsOneWidget);

    await tester.tap(loginButton);
    await tester.pump();

    expect(find.text('Field cannot be empty'), findsOneWidget);
  });
}"},{"order":13,"type":"subheading","text":"4. Key Takeaways and Best Practices"},{"order":14,"type":"bullet_point","text":"Keep tests independent: Each test must be able to run in isolation without relying on the state of previous tests."},{"order":15,"type":"bullet_point","text":"Use semantic finders: Prefer find.bySemanticsLabel or find.byKey over brittle find.byType lookups when testing complex layouts."},{"order":16,"type":"bullet_point","text":"Mock external dependencies: Never make actual network requests or write to local storage inside unit and widget tests."}]
